    ('Windows Suspicious Child Process of TieringEngineService.exe', '| tstats `security_content_summariesonly` count min(_time) as firstTime max(_time) as lastTime FROM datamodel=Endpoint.Processes WHERE Processes.parent_process_name="TieringEngineService.exe" ( Processes.process IN ( "*bitsadmin.exe*", "*cmd.exe*", "*conhost.exe*", "*cscript.exe*", "*curl.exe*", "*powershell.exe*", "*pwsh.exe*", "*rundll32.exe*", "*wmic.exe*" ) OR Processes.process_name IN ( "bitsadmin.exe", "cmd.exe", "conhost.exe", "cscript.exe", "curl.exe", "powershell.exe", "pwsh.exe", "rundll32.exe", "wmic.exe" ) ) Processes.user IN ( "*AUTHORITY*", "*System*" ) BY Processes.dest Processes.user Processes.original_file_name Processes.parent_process Processes.process_name Processes.process Processes.process_id Processes.parent_process_id Processes.parent_process_name action parent_process_exec parent_process_guid parent_process_path process_exec process_guid process_hash process_integrity_level process_path user_id vendor_product | `drop_dm_object_name(Processes)` | `security_content_ctime(firstTime)` | `security_content_ctime(lastTime)` | `windows_suspicious_child_process_of_tieringengineservice_exe_filter`'),  # La incorporo como regla 19.
