# Me conecto al servidor de splunk para establecer la conexion inicial
def connect_to_splunk(username, password, host=HOST, port=PORT,
                      owner=OWNER, app=APP, sharing=SHARING):
    try:
        service = client.connect(
            username=username,
            password=password,
            host=host,
            port=port,
            owner=owner,
            app=app,
            sharing=sharing,
        )
	# Imprimo el resultado de la conexión
        print("Conexión al servidor exitosa")
        print("-----------------------------------")
        return service
    except Exception as exc:
        print(f"Error conectando con Splunk: {exc}")
        return None


# Imprimo las busquedas guardadas en el servidor
def savedsearch_list(splunk_service):
    try:
        if splunk_service is None:
            return None
        savedsearches = splunk_service.saved_searches
        for savedsearch in savedsearches:
            print(savedsearch.name)
        print("-----------------------------------")
        return savedsearches
    except Exception as exc:
        print(f"Error listando búsquedas: {exc}")
        return None


# Creo una funcion para guardar nuevas alertas en Splunk
def create_savedsearch(savedsearch_collection, name, search, payload):
    if savedsearch_collection is None:
        print(f"No se pudo obtener la colección para: {name}")
        return False
    try:
        if name in savedsearch_collection:
            savedsearch = savedsearch_collection[name]
            savedsearch.update(search=search, **payload)
            print(f"{name}: alerta actualizada correctamente")
        else:
            savedsearch_collection.create(name, search, **payload)
            print(f"{name}: alerta creada correctamente")
        print("-----------------------------------")
        return True
    except Exception as exc:
        print(f"ERROR en {name}: {exc}")
        print("-----------------------------------")
        return False


def main():
    # Me conecto con las credenciales que configuré al principio del script.
    if PASSWORD == "PEGA_AQUI_TU_CONTRASENA_ADMIN_EN_TU_EQUIPO":
        raise SystemExit("Pega la contraseña actual de admin en PASSWORD antes de ejecutar.")
    splunk_service = connect_to_splunk(USERNAME, PASSWORD)
    if splunk_service is None:
        raise SystemExit("No se pudo conectar con Splunk; no se crearon alertas.")
   # Configuro los parametros necesarios para crear la alerta	
    collection = splunk_service.saved_searches
    payload_base = {
        "description": "Alerta de detección Sysmon.",
        "cron_schedule": "*/1 * * * *",
        "is_scheduled": "1",
        "realtime_schedule": "0",
        "disabled": "0",
        "alert_type": "number of events",
        "alert_comparator": "greater than",
        "alert_threshold": "0",
        "alert.track": "1",
        "alert.digest_mode": "1",
        "alert.suppress": "1",
        "alert.suppress.period": "60s",
        "action.email": "1",
        "action.email.to": EMAIL,
        "action.email.subject": "Splunk: $name$",
        "actions": "email",
        "dispatch.earliest_time": "-5m",
        "dispatch.latest_time": "now",
    }
    # Imprimo las alertas que han sido añadidas
    creadas = 0
    fallidas = 0
    for number, (title, search) in enumerate(RULES, start=1):
        name = f"Sysmon EventCode 1 - Nº {number:02d} - {title}"
        payload = dict(payload_base)
        payload["description"] = f"Regla {number:02d}: {title}."
        if create_savedsearch(collection, name, search, payload):
            creadas += 1
        else:
            fallidas += 1


    # Imprimo el mensaje final
    print(f"Proceso terminado. Correctas: {creadas}; fallidas: {fallidas}; total: {len(RULES)}")
    print("\nPara comprobar las alertas en Splunk dirijete a esta ruta:")
    print("Splunk Server > Search & Reporting > Settings > Searches, Reports, and Alerts")
    print("")


# Inicio el script
if __name__ == "__main__":
    main()
